def seed(db_path):
    conn = sqlite3.connect(db_path)
    # Create table if it doesn't exist
    conn.execute('''
        CREATE TABLE IF NOT EXISTS page_guides (
            id INTEGER PRIMARY KEY,
            page_key TEXT NOT NULL,
            portal TEXT NOT NULL,
            user_role TEXT,
            title TEXT NOT NULL,
            header_color TEXT NOT NULL DEFAULT "#6B21A8",
            section_what TEXT,
            section_solves TEXT,
            section_key TEXT,
            is_active INTEGER NOT NULL DEFAULT 1,
            date_added TEXT,
            last_updated TEXT
        )
    ''')
    # Upsert each guide — update if page_key exists, insert if not
    for g in PAGE_GUIDES:
        existing = conn.execute(
            "SELECT id FROM page_guides WHERE page_key = ?", [g["page_key"]]
        ).fetchone()
        if existing:
            conn.execute('''
                UPDATE page_guides SET portal=?, user_role=?, title=?, header_color=?,
                    section_what=?, section_solves=?, section_key=?, is_active=?
                WHERE page_key=?
            ''', [g["portal"], g["user_role"], g["title"], g["header_color"],
                    g["section_what"], g["section_solves"], g["section_key"], g["is_active"],
                    g["page_key"]])
        else:
            conn.execute('''
                INSERT INTO page_guides (page_key, portal, user_role, title, header_color,
                    section_what, section_solves, section_key, is_active)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ''', [g["page_key"], g["portal"], g["user_role"], g["title"], g["header_color"],
                    g["section_what"], g["section_solves"], g["section_key"], g["is_active"]])
    conn.commit()
    conn.close()
    print(f"Page guides seeded: {len(PAGE_GUIDES)} entries")

if __name__ == "__main__":
    db = os.environ.get("DB_PATH", "project_phoenix.db")
    seed(db)
